INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `QuestGiverTextWindow`, `QuestGiverTargetName`, `QuestTurnTextWindow`, `QuestTurnTargetName`) VALUES
(3117,"ruRU","Выгравированный знак","Этот знак был передан мне посланником нашей наставницы охотников, Аянны. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Аянне.","Поговорите с Аянной Вечной Странницей в Альдрассиле, что в Тенистой долине.","","","","","",""),
(10345,"ruRU","Усеял мертвыми костями...","Ты видишь эти трупы, |3-6($r)? В этом убийстве повинен Арконус. Он высосал их досуха, оставив лишь мертвую плоть. Но не дай виду этих трупов обмануть тебя! Внутри них скрываются мясожоры, готовые наброситься на любого, кто подойдет поближе.$B$BУ меня есть приказ – оставаться здесь, пока не прибудет подмога. Однако ты можешь взять мой поджигатель и уничтожить эти высохшие трупы, которыми забита шахта. Так или иначе, миссия должна быть выполнена!","Примените поджигатель Протектората к 12 высохшим трупам. Когда задача будет завершена, верните поджигатель Протектората посланнику Араксису, находящемуся у входа в шахту Зеон.","","Вернитесь к посланнику Араксису у входа в шахту Зеон в Пустоверти.","","","",""),
(26947,"ruRU","Обучение лесного жителя","Говоря о калдорай, большинство имеет в виду друидов или часовых, но путь охотника не менее древний и почетный.$B$BЯ наблюдала за тобой и вижу, что у тебя есть кое-какой опыт в обращении с луком. По мере накопления умений тебе будут открываться новые возможности.$B$BЯ хочу, чтобы ты $gполучил:получила; новый опыт и $gвыяснил:выяснила;, как делать что-то новое. Затем используй новые умения на тренировочном манекене неподалеку от юго-восточной окраины Альдрассила.","Достигните 3-го уровня, чтобы изучить способность \"Верный выстрел\". Найдите тренировочный манекен к юго-востоку от Альдрассила и опробуйте на нем эту способность пять раз.","","Вернитесь к Аянне Вечной Страннице в Альдрассил.","","","",""),
(28713,"ruRU","Природное равновесие","Привет, $n. Мое имя Илталайн. В Тенистой долине я учу таких, как ты, и забочусь о том, чтобы не нарушалось природное равновесие.$B$BВ этом году весна была очень дождливой, и в результате одни звери чувствуют себя прекрасно, а другие, наоборот, страдают. К сожалению, ночные саблезубы слишком расплодились: если ничего не предпринять, они истребят всю живность в этом лесу.$B$BИди же, |3-6($c), и уменьши численность саблезубов, чтобы в природе восстановилась гармония.","Убейте 6 молодых ночных саблезубов.","","Поговорите с Илталайном в Тенистой долине.","","","",""),
(28714,"ruRU","Мох скверны","Похоже, ты знаешь, что делаешь. Значит, я могу дать тебе более важное поручение.$B$BНасколько тебе известно, Тельдрассил был очищен от порчи. Но все-таки там что-то осталось. Звери не успокоились, и местных жителей одолевают разные беды.$B$BИди на запад и разберись с тамошними греллями. Проверь, нет ли у них мха скверны. Это поможет мне понять, откуда здесь берется скверна.","Соберите 6 пучков мха Скверны, отобрав их у греллей, которые находятся к западу от Илталайна.","","Вернитесь к Илталайну в Тенистую долину.","","","",""),
(28715,"ruRU","Демонические воры","Мерзкие грелли! Они снова воруют наши припасы.$B$BЯ почти уверен в том, что они спрятали мои сумки в своем лагере, к западу отсюда. Принеси мне эти сумки, и я с радостью награжу тебя.","Найдите украденные у Мелитара сумки на западе, рядом с греллями.","","Поговорите с Мелитаром Оленьим Шлемом в Альдрассиле.","","","",""),
(28723,"ruRU","Жрица луны","Теперь, когда ты уже умеешь применять свою новую способность, возможно, ты поможешь очистить Тенистую долину от порчи.$B$BДентария Серебристая Поляна, жрица Луны, предложила нам свою помощь. Она находится между двумя водоемами, к северу от нашего великого дерева. Обойди дерево, |3-6($c), найди жрицу и предложи ей свою помощь.","Поговорите с Дентарией Серебристой Поляной в центре Тенистой долины между двумя водоемами.","","","","","",""),
(28724,"ruRU","Противоядие для Иверрона","Нашего друга Иверрона покусали местные пауки и отравили его своим ядом. Я могу поддерживать Иверрона в его нынешнем состоянии, но для приготовления противоядия мне нужна твоя помощь.$B$BПо берегам этих водоемов растут лунные лилии. Они обладают целебными свойствами, и я могу объединить их с другими ингредиентами и сделать противоядие для Иверрона.$B$BПожалуйста, набери этих лилий. В здешних краях их много, можно увидеть даже отсюда.","Соберите 7 лунных лилий.","","Поговорите с Дентарией Серебристой Поляной между водоемов в Тенистой долине.","","","",""),
(28734,"ruRU","Просьба Мелитара","Тебе нужно поговорить с Мелитаром. Кажется, у него уже были какие-то проблемы с греллями.$B$BЕсли ты поможешь ему, то, возможно, он выделит тебе место для хранения товаров.","Идите в Тенистую долину и поговорите с Мелитаром Оленьим Шлемом.","","","","","",""),
(28765,"ruRU","Дать отпор!","Стало быть, ты новобранец из Штормграда? Я маршал Макбрайд, командир гарнизона. Добро пожаловать в строй!$B$B<Макбрайд просматривает какие-то бумаги.>.$B$B$n. $n, так?$B$BТы как раз вовремя. Оркам Черной горы удалось проникнуть в Североземье через горный разлом. Мои солдаты делают все возможное, чтобы оттеснить врага, но их становится все больше и больше.$B$BОтправляйся на северо-запад в лес и истреби там вторгшихся воргов из клана Черной горы! Приди на помощь нашим войскам!","Убейте 6 боевых воргов клана Черной горы.","","Вернитесь к маршалу Макбрайду в Аббатство Североземья, что находится в Элвиннском лесу.","Это боевой ворг клана Черной горы.","Боевой ворг клана Черной горы","","")
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) VALUES
(3117,"ruRU","Когда обретешь достаточно опыта в Тенистой долине, приходи ко мне – я помогу тебе постичь умения охотника и осознать твои собственные возможности.$B$BЭто опасные времена, $n, и даже умения твоих питомцев нельзя принимать как должное – в мире существуют вещи куда более опасные, нежели ты можешь вообразить. Да хранит тебя Элуна, $n, я буду ждать твоего возвращения."),
(10345,"ruRU","Ты $gспас:спасла; мои обмотки, $n. Протекторат узнает о твоих деяниях."),
(26947,"ruRU","Ты быстро постигаешь нашу науку."),
(28713,"ruRU","Ты хорошо исполняешь свой долг, $n."),
(28714,"ruRU","То, что ты $gсделал:сделала; для созданий Тенистой долины, достойно награды, $n.$B$BОднако ты $gубедил:убедила; меня, что мои страхи не были беспочвенными. Несмотря на благословение Тельдрассила, грелли все еще страдают от мха Скверны. В этом дереве таится нечто ужасное. Мне остается надеяться только на то, что племя фурболгов Кривой Сосны не затронуто порчей, или всем нам грозит большая опасность.$B$BЯ посвящу еще некоторое время изучению этого вопроса и свяжусь с теми, кто может помочь. Спасибо тебе, |3-6$c."),
(28715,"ruRU","Слава Элуне! И тебе тоже, |3-6$c.$B$BЭти сумки нужны многим молодым ночным эльфам, но я с радостью дам тебе одну в качестве награды. Думаю, она тебе пригодится.$B$BСчастливого пути."),
(28723,"ruRU","Хорошо, что ты здесь. Похоже, процесс обучения идет довольно быстро."),
(28724,"ruRU","Это то, что нужно. Спасибо, $n. Ты действуешь очень быстро, и это прекрасно."),
(28734,"ruRU","Тебя прислал Илталайн? Весьма умно с его стороны. Мне в самом деле нужна помощь."),
(28765,"ruRU","Ты $gвыиграл:выиграла; для нас еще немного времени, $n, но сейчас у нас есть еще большие проблемы.")
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) VALUES
(3117,"ruRU","Ты наконец-то здесь, $n, хотя и не так скоро, как я надеялась. Добро пожаловать в Тенистую долину.$B$BНадеюсь, ты $gполучил:получила; мое послание, будучи в добром здравии и расположении духа?$B$BКак я говорила ранее, я намереваюсь обучить тебя охотничьему мастерству: приручению зверей, которые помогут тебе в бою, стрельбе из лука с безукоризненной меткостью и уважению к землям, которые мы зовем домом, так и к тем, что лежат за очерченными нами пределами."),
(10345,"ruRU","Удалось ли тебе найти Йасека?"),
(28713,"ruRU","Еще многое предстоит сделать, $n. Возвращайся ко мне, как только ты сократишь численность ночных саблезубов."),
(28714,"ruRU","Подтверди мои опасения, $n. Принеси мне мох Скверны от греллей."),
(28715,"ruRU","У меня не будет провианта для покупателей, пока мне не вернут украденное добро. Ну как, удалось?"),
(28724,"ruRU","Наш дорогой друг чувствует себя не очень хорошо, и даже мои лекарства не помогают. Тебе удалось добыть нужные ингредиенты?"),
(28765,"ruRU","Ты $gотбил:отбила; атаки боевых воргов клана Черной горы?")
