-- ruRU quest locales, converted from the old wide-format `locales_quest`.
-- That single table was split into three: the reward and completion texts now
-- live in quest_offer_reward_locale and quest_request_items_locale.
-- ON DUPLICATE KEY UPDATE keeps the file re-runnable on a populated database.
ON DUPLICATE KEY UPDATE `Title`=VALUES(`Title`), `Details`=VALUES(`Details`), `Objectives`=VALUES(`Objectives`), `EndText`=VALUES(`EndText`), `CompletedText`=VALUES(`CompletedText`), `QuestGiverTextWindow`=VALUES(`QuestGiverTextWindow`), `QuestGiverTargetName`=VALUES(`QuestGiverTargetName`), `QuestTurnTextWindow`=VALUES(`QuestTurnTextWindow`), `QuestTurnTargetName`=VALUES(`QuestTurnTargetName`);

ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);

ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
